from lib import *
S = SS('u166')
R = J('u166'); a1 = R['audit1']; a2 = R['audit2']; dn = R['deny1']; nrej = dn['lines'].count('error[rejected]: failed to satisfy license requirements')
steps = [
    step("被审计的项目:main 里只有 println!(\"hello\"),Cargo.toml 却固定了三个老版本依赖:smallvec =1.6.0、chrono =0.4.19(关掉默认特性)、atty =0.2.14。cargo tree 显示 12 个 crate 的依赖图(atty→libc,chrono→num-integer→num-traits 等),依赖项里没有任何一个被 main 调用。审计看的是锁文件里的版本。", t=tl(S(1)), done=lidx(S(1), 'smallvec = "=1.6.0"', 'chrono', 'atty'), kv=KV([['直接依赖', 'smallvec 1.6.0 / chrono 0.4.19 / atty 0.2.14'], ['锁文件里的 crate', '12 个']], ['直接依赖'])),
    step(f"cargo audit(cargo-audit 0.22.2)先从 GitHub 更新 RustSec 漏洞库(日志「Fetching advisory database」,载入 {R['json']['adv']} 条公告),再扫描 Cargo.lock:退出码 1,「2 vulnerabilities found」+「2 allowed warnings」。漏洞:RUSTSEC-2020-0159 chrono 0.4.19(localtime_r 可能段错误,解决:>=0.4.20);RUSTSEC-2021-0003 smallvec 1.6.0(SmallVec::insert_many 缓冲区溢出,严重度 9.8 critical,解决:>=1.6.1)。警告:atty 0.2.14 已无人维护(RUSTSEC-2024-0375)、有潜在的未对齐读取(RUSTSEC-2021-0145,unsound)。本地漏洞库最近提交 {R['dbcommit'][:10]}。", t=tl(S(2)), mark=lidx(S(2), 'RUSTSEC-2020-0159', 'RUSTSEC-2021-0003', '2 vulnerabilities found'), done=lidx(S(2), 'unmaintained', 'unsound', 'allowed warnings'), kv=KV([['漏洞', '2 条(chrono、smallvec)'], ['警告', '2 条(atty:unmaintained、unsound)'], ['退出码', '1']], ['漏洞'])),
    step(f"加 --no-fetch 跳过联网更新,只用本地漏洞库:{a2['secs']} 秒(上一节联网更新的那次是 {a1['secs']} 秒)。CI 里常常先拉一次库再多次扫描;离线环境用 --no-fetch,但库会过时。", t=tl(S(3)), b=bars([['默认(联网更新)', a1['secs'], f"{a1['secs']} s"], ['--no-fetch', a2['secs'], f"{a2['secs']} s"]], a1['secs'], done=[0, 1]), kv=KV([['联网更新', f"{a1['secs']} 秒"], ['--no-fetch', f"{a2['secs']} 秒"]], ['--no-fetch'])),
    step("--json 输出可交给脚本:vulnerabilities.found = True、count = 2;每个漏洞带 advisory.id、package(名称与版本)、versions.patched(smallvec 是 >=0.6.14, <1.0.0 与 >=1.6.1 两段)、cvss(smallvec 为 CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H);warnings 按类别分成 unmaintained 与 unsound。lockfile.dependency-count = 12,database.advisory-count = 1279。", t=tl(S(4)), done=lidx(S(4), 'vulnerabilities.found', 'RUSTSEC-2020-0159', 'RUSTSEC-2021-0003'), mark=lidx(S(4), 'warnings 分类'), kv=KV([['count', '2'], ['warnings', 'unmaintained、unsound'], ['dependency-count', '12']], ['count'])),
    step("--ignore 排除指定公告:忽略那两条漏洞后,cargo audit 退出码 0,仍然列出 2 个警告(「2 allowed warnings found」);再加 --deny warnings,警告也算失败,退出码 1。这样可以对「已评估、暂不处理」的公告做显式豁免,而不是关掉整个检查。", t=tl(S(5)), done=lidx(S(5), '退出码 0'), mark=lidx(S(5), '--deny warnings', 'allowed warnings'), kv=KV([['--ignore 两条漏洞', '退出码 0'], ['再加 --deny warnings', '退出码 1']], ['再加 --deny warnings'])),
    step("修复:把版本要求放宽成 smallvec 1.6.1、chrono 0.4.20 并去掉 atty,cargo update 后解析到 chrono 0.4.45、smallvec 1.16.2(chrono 因为新版依赖 iana-time-zone,锁文件里变成 39 个 crate)。再运行 cargo audit:退出码 0,没有漏洞也没有警告。注意审计通过并不代表依赖更少:这次依赖图反而从 12 个变成了 39 个。", t=tl(S(6)), done=lidx(S(6), 'chrono v0.4.45', 'smallvec v1.16.2', '退出码 0'), kv=KV([['chrono', '0.4.19 → 0.4.45'], ['smallvec', '1.6.0 → 1.16.2'], ['crate 数', '12 → 39']], ['crate 数'])),
    step("cargo audit 不看调用图:第二节里 main 根本没有使用 smallvec 的 insert_many,报告照样出现 —— 它的判断依据是 Cargo.lock 里「有没有这个版本」。恢复旧依赖后再审计,退出码又是 1。这意味着有些报告是误报(代码没走到那条路径),也可能漏掉没有公告的问题。", t=tl(S(7)), mark=lidx(S(7), '退出码 1', '照样报告'), kv=KV([['判断依据', 'Cargo.lock 的版本'], ['是否看调用', '不看']], ['判断依据'])),
    step(f"cargo deny(0.20.2)在审计之外还管许可证、重复版本、来源:cargo deny init 生成的 deny.toml 有 graph、output、advisories、licenses、bans、sources 几个段落。用默认模板 check:退出码 5,「advisories FAILED, bans ok, licenses FAILED, sources ok」;许可证一栏有 {nrej} 条 failed to satisfy license requirements(模板的 allow 列表是空的),本包因为没有 license 字段被判 unlicensed;advisories 一栏除了两个漏洞,还把 unmaintained 与 unsound 当作 error。自己写 deny.toml 只允许 MIT/Apache-2.0/Unicode-3.0 后,许可证一栏只剩本包 au 没写 license 字段这一条 error;只检查 licenses 的退出码是 {R['deny_lic']}。", t=tl(S(8)), mark=lidx(S(8), 'advisories FAILED', 'error[vulnerability]', 'error[unmaintained]', 'error[unsound]'), done=lidx(S(8), 'bans ok', 'sources ok', '退出码 5'), kv=KV([['默认模板', 'advisories、licenses 失败'], ['bans / sources', 'ok'], ['退出码', '5(只查 licenses 时 4)']], ['默认模板'])),
    step("放进 CI 就是一行命令:cargo audit 的退出码就是门禁。旧锁文件:退出码 1,这一步失败;升级依赖后:退出码 0,通过。(没有验证:在 GitHub Actions 里的实际运行,见 CI 一篇(Rust 项目持续集成)里的说明。)", t=tl(S(9)), mark=lidx(S(9), '退出码 1'), done=lidx(S(9), '退出码 0'), kv=KV([['旧锁文件', 'cargo audit 退出码 1'], ['升级后', '退出码 0']], ['旧锁文件'])),
]
A = mkart('u166', 166, 'Rust,cargo-audit,cargo-deny,依赖安全,RustSec,真实验证,动画演示',
    f'用 cargo-audit 0.22.2 与 cargo-deny 0.20.2 审计一个固定了 smallvec 1.6.0、chrono 0.4.19、atty 0.2.14 的项目:报告 2 个漏洞(含 CVSS 9.8 的 smallvec)与 2 个警告;升级依赖后退出码 0;审计只看 Cargo.lock 不看调用图;cargo deny 另查许可证、重复版本与来源。',
    '依赖里的已知漏洞,编译器不会告诉你。RustSec 维护了公告数据库,cargo audit 拿它去对 Cargo.lock。这篇用故意固定的老版本依赖,把审计的输出、JSON、豁免、修复,以及 cargo deny 的另外几类规则逐个跑一遍。',
    [('2 + 2', 'cargo audit 报告的漏洞数 + 警告数'), ('9.8', 'smallvec 1.6.0 公告的 CVSS 严重度(critical)'), ('1279', '本机拉到的 RustSec 公告数(漏洞库提交日期 ' + R['dbcommit'][:10] + ')')],
    [('被审计的项目', '<p>依赖锁定见<a href="rust-cargo-lock.html">Cargo.lock</a>,依赖解析见<a href="rust-cargo-dependency-resolution.html">Cargo 依赖解析</a>。</p>'), ('cargo audit', None), ('离线与耗时', None), ('JSON 输出', None), ('忽略与严格模式', None), ('修复', None), ('只看版本,不看调用', None), ('cargo deny', None), ('放进 CI', '<p>完整的持续集成流程见<a href="rust-ci.html">Rust 项目持续集成</a>。</p>')],
    steps, [ENV_N + '。cargo-audit 0.22.2、cargo-deny 0.20.2(cargo install --locked,装在隔离目录);RustSec 漏洞库通过代理从 GitHub 拉取', '没有验证:漏洞库里更新的公告、cargo audit fix(自动改 Cargo.toml)、cargo deny 的 bans 规则(重复版本、wildcard、skip)在真实多版本冲突项目里的表现、私有 registry 与 git 依赖的来源规则、对 yanked 版本的检测', '本篇用的是固定在老版本的依赖,结果会随 RustSec 漏洞库的更新而变化'], 'cargo audit')
